package io.github.diodeme.ji.telemetry;

import java.util.Map;
import java.util.concurrent.CompletionStage;
import java.util.function.Function;

final class GuardedTelemetrySpan implements TelemetrySpan {
    private final TelemetrySink sink;
    private final TelemetrySpan delegate;

    GuardedTelemetrySpan(TelemetrySink sink, TelemetrySpan delegate) {
        this.sink = sink;
        this.delegate = delegate;
    }

    @Override
    public <T> T inSpan(SpanSpec spec, Function<TelemetrySpan, T> callback) {
        return new SafeTelemetryContext(sink, childParent()).inSpan(spec, callback);
    }

    @Override
    public <T> CompletionStage<T> inSpanAsync(SpanSpec spec, Function<TelemetrySpan, CompletionStage<T>> callback) {
        return new SafeTelemetryContext(sink, childParent()).inSpanAsync(spec, callback);
    }

    @Override public void setAttributes(Map<String, TelemetryValue> attributes) { passive(() -> delegate.setAttributes(attributes)); }
    @Override public void addEvent(String name, Map<String, TelemetryValue> attributes) { passive(() -> delegate.addEvent(name, attributes)); }
    @Override public void recordMetric(MetricPoint point) { passive(() -> delegate.recordMetric(point)); }
    @Override public void setStatus(SpanStatus status) { passive(() -> delegate.setStatus(status)); }
    @Override public void settle(boolean failed) { passive(() -> delegate.settle(failed)); }

    @Override
    public SpanParent childParent() {
        try {
            return delegate.childParent();
        } catch (Throwable ignored) {
            return SpanParent.root();
        }
    }

    private static void passive(Runnable operation) {
        try {
            operation.run();
        } catch (Throwable ignored) {
            // Telemetry is diagnostics only and never changes the business result.
        }
    }
}
